from __future__ import annotations
from itertools import product
from typing import Iterable

def count_colorings(n: int, edges: Iterable[tuple[int, int]], q: int) -> int:
    """Return the number of proper q-colorings by exhaustive enumeration."""
    edge_list = list(edges)
    return sum(all(c[u] != c[v] for u, v in edge_list)
               for c in product(range(q), repeat=n))

def falling_factorial(q: int, n: int) -> int:
    if n > q:
        return 0
    answer = 1
    for k in range(n):
        answer *= q - k
    return answer

if __name__ == "__main__":
    for q in range(6):
        empty = count_colorings(4, [], q)
        complete = count_colorings(4, ((u, v) for u in range(4) for v in range(u + 1, 4)), q)
        assert empty == q ** 4
        assert complete == falling_factorial(q, 4)
        print(q, empty, complete)

from __future__ import annotations
from itertools import product

def partition_triangle_deletion(q: int) -> tuple[int, int]:
    """Partition colorings of the path K3-e by endpoint equality."""
    unequal = equal = 0
    for c in product(range(q), repeat=3):
        if c[0] != c[1] and c[1] != c[2]:
            if c[0] == c[2]:
                equal += 1
            else:
                unequal += 1
    return unequal, equal

if __name__ == "__main__":
    for q in range(1, 7):
        unequal, equal = partition_triangle_deletion(q)
        assert unequal == q * max(q - 1, 0) * max(q - 2, 0)
        assert equal == q * max(q - 1, 0)
        print(f"q={q}: deletion={unequal + equal}, original={unequal}, contraction={equal}")

from __future__ import annotations
from itertools import product

def count(n: int, edges: list[tuple[int, int]], q: int) -> int:
    return sum(all(c[u] != c[v] for u, v in edges)
               for c in product(range(q), repeat=n))

if __name__ == "__main__":
    edge = [(0, 1)]
    isolated: list[tuple[int, int]] = []
    union = [(0, 1)]  # vertex 2 is isolated
    for q in range(1, 7):
        left = count(2, edge, q)
        right = count(1, isolated, q)
        together = count(3, union, q)
        assert together == left * right
        print(f"q={q}: {together} = {left} x {right}")

