from __future__ import annotations
from functools import lru_cache
from typing import Iterable
Graph = tuple[int, tuple[tuple[int, int], ...]]

def graph(n: int, edges: Iterable[tuple[int, int]]) -> Graph:
    return n, tuple(sorted({tuple(sorted(e)) for e in edges if e[0] != e[1]}))

def delete(g: Graph, e: tuple[int, int]) -> Graph:
    n, edges = g
    e = tuple(sorted(e))
    return graph(n, (x for x in edges if x != e))

def contract(g: Graph, e: tuple[int, int]) -> Graph:
    n, edges = g
    a, b = sorted(e)
    kept = [v for v in range(n) if v != b]
    label = {v: i for i, v in enumerate(kept)}
    out = []
    for u, v in edges:
        u = a if u == b else u
        v = a if v == b else v
        if u != v:
            out.append((label[u], label[v]))
    return graph(n - 1, out)

@lru_cache(None)
def chromatic_count(g: Graph, q: int) -> int:
    n, edges = g
    if not edges:
        return q ** n
    e = edges[0]
    return chromatic_count(delete(g, e), q) - chromatic_count(contract(g, e), q)

if __name__ == "__main__":
    triangle = graph(3, [(0, 1), (1, 2), (0, 2)])
    print([chromatic_count(triangle, q) for q in range(1, 7)])

